#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Armors;
using MVZ2.GameContent.Damages;
using MVZ2.Vanilla.Callbacks;
using MVZ2.Vanilla.Effects;
using MVZ2.Vanilla.Entities;
using PVZEngine.Armors;
using PVZEngine.Buffs;
using PVZEngine.Damages;
using PVZEngine.Entities;
using PVZEngine.Level;
using PVZEngine.Models;
using UnityEngine;

namespace MVZ2.Vanilla.Armors
{
    public static class VanillaArmorExt
    {
        public static void DamageBlink(this Armor armor)
        {
            if (armor != null && !armor.HasBuff<ArmorDamageColorBuff>())
                armor.AddBuff<ArmorDamageColorBuff>();
        }
        public static void SetModelDamagePercent(this Armor armor)
        {
            armor.SetModelDamagePercent(armor.Health, armor.GetMaxHealth());
        }
        public static void SetModelDamagePercent(this Armor armor, float health, float maxHealth)
        {
            armor.SetModelDamagePercent(1 - health / maxHealth);
        }
        public static void SetModelDamagePercent(this Armor armor, float percent)
        {
            armor.SetModelProperty("DamagePercent", percent);
        }

        private static int PreArmorTakeDamage(this Armor armor, ArmorDamageInputPart input, ArmorDamageOutputPart result)
        {
            var param = new VanillaLevelCallbacks.PreArmorTakeDamageParams(input, armor, result);
            return input.Entity.Level.Triggers.RunCallbackWithResultFiltered(VanillaLevelCallbacks.PRE_ARMOR_TAKE_DAMAGE, param, DamageStates.CONTINUE, armor.Definition.GetID());
        }
        private static void PostArmorTakeDamage(this Armor armor, ArmorDamageOutputPart result)
        {
            var param = new VanillaLevelCallbacks.PostArmorTakeDamageParams(result);
            result.Entity.Level.Triggers.RunCallbackFiltered(VanillaLevelCallbacks.POST_ARMOR_TAKE_DAMAGE, param, armor.Definition.GetID());
        }
        public static ArmorDamageOutputPart? TakeDamage(this Armor armor, ArmorDamageInputPart input)
        {
            if (!Armor.Exists(armor))
                return null;

            var entity = input.Entity;
            var shell = armor.GetShellDefinition();
            var result = new ArmorDamageOutputPart(input, shell);

            var damageState = armor.PreArmorTakeDamage(input, result);
            if (damageState == DamageStates.BREAK)
            {
                return null;
            }
            else if (damageState == DamageStates.RETURN)
            {
                return result;
            }

            if (shell != null && !input.HasEffect(VanillaDamageEffects.NO_MODIFICATION))
            {
                shell.EvaluateDamage(input);
            }

            // Apply Damage
            var actualAmount = input.Amount;
            if (actualAmount > 0)
            {
                float hpBefore = armor.Health;
                armor.Health -= actualAmount;

                var effectiveAmount = Mathf.Min(hpBefore, actualAmount);
                var overflowAmount = input.GetOverflowAmount(hpBefore, actualAmount);
                result.SetDamageAmount(actualAmount, effectiveAmount, overflowAmount);
                result.Fatal = hpBefore > 0 && armor.Health <= 0;
                if (result.Fatal)
                {
                    var destroyInfo = new ArmorDestroyInfo(entity, armor, armor.Slot, input.Effects, input.Source, result);
                    armor.Destroy(destroyInfo);
                }
            }
            else
            {
                result.SetDamageAmount(actualAmount, 0, 0);
            }

            if (result.HasDamageAmount())
            {
                armor.PostArmorTakeDamage(result);
            }

            return result;
        }
        public static HealOutput? HealEffects(this Armor armor, float amount, ILevelSourceReference? source)
        {
            var result = armor.HealSourced(amount, source);
            if (result == null)
                return null;
            if (result.RealAmount >= 0)
            {
                armor.Owner.AddTickHealing(result.RealAmount);
            }
            return result;
        }
        public static HealOutput? HealSourced(this Armor armor, float amount, ILevelSourceReference? source)
        {
            return VanillaEntityExt.Heal(new HealInput(amount, armor.Owner, armor, source));
        }
        #region ±»¼â´Ì´Ý»Ù
        public static bool TryDestroyBySpikes(this Armor armor, Entity source)
        {
            bool destroyed = false;
            var definition = armor.Definition;
            var count = definition.GetBehaviourCount();
            for (int i = 0; i < count; i++)
            {
                var behaviour = definition.GetBehaviourAt(i);
                if (behaviour is not IDestroyBySpikesArmorBehaviour entityBehaviour)
                    continue;
                if (entityBehaviour.CanBeDestroyedBySpikes(armor, source))
                {
                    entityBehaviour.DestroyBySpikes(armor, source);
                    destroyed = true;
                }
            }
            return destroyed;
        }
        #endregion
    }
}
